# --- Mockito 기본 문법 ---

@DisplayName("주문을 조회하면 저장된 주문이 반환된다")
@Test
void getOrder() {
    // given
    Order order = new Order(List.of(new Americano()));
    when(orderRepository.findById(1L)).thenReturn(Optional.of(order));

    // when
    OrderResponse response = orderService.getOrder(1L);

    // then
    assertThat(response.getTotalPrice()).isEqualTo(4000);
}

$ ./gradlew test --tests OrderServiceTest

OrderServiceTest > 주문을 조회하면 저장된 주문이 반환된다 PASSED

#   통과한다

#   그런데 // given 아래 첫 줄이 when( 이다

# --- BDDMockito ---

import static org.mockito.BDDMockito.given;

@DisplayName("주문을 조회하면 저장된 주문이 반환된다")
@Test
void getOrder() {
    // given
    Order order = new Order(List.of(new Americano()));
    given(orderRepository.findById(1L)).willReturn(Optional.of(order));

    // when
    OrderResponse response = orderService.getOrder(1L);

    // then
    assertThat(response.getTotalPrice()).isEqualTo(4000);
}

$ ./gradlew test --tests OrderServiceTest

OrderServiceTest > 주문을 조회하면 저장된 주문이 반환된다 PASSED

#   같은 결과다

#   given 절에 given( 이 있다

# --- 동작이 같은지 확인 ---

#   스텁을 안 맞게 만들어 본다

given(orderRepository.findById(2L)).willReturn(Optional.of(order));

OrderServiceTest > 주문을 조회하면 저장된 주문이 반환된다 FAILED
    java.util.NoSuchElementException: No value present

#   1L 을 부르는데 2L 만 스텁했다

#   when(...).thenReturn(...) 판도 같은 오류다

#   BDDMockito 는 Mockito 를 상속한다

$ javap -cp build/classes org.mockito.BDDMockito | head -3
public class org.mockito.BDDMockito extends org.mockito.Mockito {

#   표기법만 다르다

# --- verify 쪽 ---

// then
verify(orderRepository).findById(1L);

#   또는

then(orderRepository).should().findById(1L);

$ ./gradlew test --tests OrderServiceTest

OrderServiceTest > 주문을 조회하면 저장된 주문이 반환된다 PASSED

#   둘 다 통과한다

#   호출 안 됐을 때의 메시지도 같다

OrderServiceTest > ... FAILED
    Wanted but not invoked:
    orderRepository.findById(1L);
    Actually, there were zero interactions with this mock.

# --- 세 칸에서 이름 뽑기 ---

// given
cafeKiosk.add(new Americano());

// when
cafeKiosk.remove(new Latte());

// then  -> 예외

#   읽으면
#   "아메리카노를 담은 상태에서 라떼를 빼면 예외가 난다"

#   줄이면
#   "담지 않은 음료를 빼면 예외가 난다"

@DisplayName("담지 않은 음료를 빼면 예외가 난다")
@Test
void removeNotExists() {
    // given
    cafeKiosk.add(new Americano());

    // when & then
    assertThatThrownBy(() -> cafeKiosk.remove(new Latte()))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessage("주문 목록에 없는 음료입니다.");
}

CafeKioskTest > 담지 않은 음료를 빼면 예외가 난다 PASSED

#   예외 테스트는 when 과 then 이 붙는다
#   // when & then 으로 표시한다

# --- 2.2절의 이름과 비교 ---

#   전
#     "주문 목록에 없는 음료를 빼면 예외가 난다"

#   후
#     "담지 않은 음료를 빼면 예외가 난다"

#   '주문 목록' 은 구현 용어에 가깝다
#   '담지 않은' 이 사용자의 말이다

#   4.2절의 도메인 용어 규칙이다

